/**
 * run-view — the record type of schema id `specstride.view/1`, annex G, §G.6.
 *
 * Generated by `scripts/types.mjs` from `schemas/run-view.schema.json` (research.md,
 * D-1) — do not edit; re-run the `build` script of the package instead. The
 * fields keep the meaning, the type in words and the required cell of the
 * annex as documentation.
 */
export interface RunView {
  /**
   * The schema id with its major
   *
   * Type in words: Text.
   */
  schema: unknown;
  /**
   * Time of the projection; the only wall-clock field of the view
   *
   * Type in words: Timestamp, UTC.
   */
  now: string;
  /**
   * Identity: the run id
   *
   * Type in words: Text.
   */
  runId: string | null;
  /**
   * Identity: the workspace id
   *
   * Type in words: Text.
   */
  workspaceId: string | null;
  /**
   * Identity: the feature slug
   *
   * Type in words: Text.
   */
  feature: string | null;
  /**
   * File, byte offset and last `seq` after the last complete line read
   *
   * Type in words: Record.
   */
  cursor: unknown;
  /**
   * A written state of annex E §E.2, or `none`
   *
   * Type in words: Member of a closed set.
   */
  state: unknown;
  /**
   * Time of the last transition
   *
   * Type in words: Timestamp.
   */
  stateSince: string | null;
  /**
   * Number of the last transition
   *
   * Type in words: Text.
   */
  transition: string | null;
  /**
   * The `st` value: the written state, or `dead`, `stale`, `launch-abandoned` or `unknown` where a derived condition holds
   *
   * Type in words: Text.
   */
  display: string;
  /**
   * `alive`, `dead`, `foreign`, `unknown`, `not-applicable`
   *
   * Type in words: Member of a closed set.
   */
  liveness: unknown;
  /**
   * The three derived conditions; derived by a reader and never written
   *
   * Type in words: Record.
   */
  conditions: {
    /**
     * The owner is gone
     *
     * Type in words: Truth value.
     */
    dead: boolean;
    /**
     * Null, or the reason, with the major found and the range accepted for `event-major-out-of-range`
     *
     * Type in words: Record or null.
     */
    stale: unknown;
    /**
     * A launch without an outcome and without a lease past the handshake limit
     *
     * Type in words: Truth value.
     */
    launchAbandoned: boolean;
  };
  /**
   * Launch id, reason, outcome, engine start ordinal
   *
   * Type in words: Record.
   */
  launch: {
    launchId: string | null;
    reason: string | null;
    outcome: string | null;
    engineStartId: string | number | null;
  };
  /**
   * The position of the run
   *
   * Type in words: Record.
   */
  progress: {
    phase: number | null;
    phases: number | null;
    phaseAttempt: number | null;
    pass: number | null;
    rejects: number;
    malformed: number;
    units: unknown;
    elapsedSeconds: number;
  };
  /**
   * `classic` or `micro`, the micro level, the reason a layer is off
   *
   * Type in words: Record.
   */
  strategy: {
    strategy: "classic" | "micro" | null;
    microLevel: number | null;
    layerOffReason: string | null;
  };
  /**
   * Number, title or null, evidence exists, approved, feedback exists
   *
   * Type in words: List of records.
   */
  phases: Array<{
    number: number;
    title: string | null;
    evidence: boolean;
    approved: boolean;
    feedback: boolean;
  }>;
  /**
   * Card id, feature, phase, lane, rule id of the lane, flags
   *
   * Type in words: List of records.
   */
  cards: Array<{
    id: string;
    feature: string | null;
    phase: number | null;
    lane: unknown;
    ruleId: unknown;
    flags: {
      dead: boolean;
      stale: boolean;
      yielded: boolean;
    };
  }>;
  /**
   * The eight lanes in order, each with the ids of its cards
   *
   * Type in words: List of records.
   */
  lanes: Array<{
    lane: unknown;
    cards: Array<string>;
  }>;
  /**
   * Id and version of the table used
   *
   * Type in words: Record.
   */
  laneTable: {
    id: string;
    version: string;
  };
  /**
   * The attention items, in the order of the table of F129-FR-017 and then by `since`
   *
   * Type in words: List of records.
   */
  attention: Array<unknown>;
  /**
   * How many attention items were left out of the bound of 50
   *
   * Type in words: Whole number.
   */
  attentionOmitted: number;
  /**
   * Scope, role, cost class, spent, tokens, cap, fraction, level, notional, quota
   *
   * Type in words: List of records.
   */
  budget: Array<unknown>;
  /**
   * How many budget rows were left out of the bound of 64
   *
   * Type in words: Whole number.
   */
  budgetOmitted: number;
  /**
   * Holders of the run token: kind, class, process id; count of entries cut
   *
   * Type in words: Record.
   */
  processes: {
    holders: Array<{
      kind: string | null;
      class: string | null;
      pid: number | null;
    }>;
    omitted: number;
    cut: number;
  };
  /**
   * Suggested seconds until the next reading; unchanged count; relaunch budget
   *
   * Type in words: Record or null.
   */
  supervision: unknown;
  /**
   * Latest tool with a summary; observability mode and reason
   *
   * Type in words: Record.
   */
  activity: {
    latestTool: unknown;
    observabilityMode: string | null;
    observabilityReason: string | null;
  };
  /**
   * Sink and delivery state
   *
   * Type in words: List of records.
   */
  telemetry: Array<{
    sink: string;
    delivery: string | null;
  }>;
  /**
   * The newest rows and the number of rows left out
   *
   * Type in words: Record.
   */
  timeline: {
    rows: Array<{
      seq: number;
      ts: string | null;
      kind: string;
      text: string | null;
    }>;
    omitted: number;
  };
  /**
   * Present only with parallel units on; null where the option is off
   *
   * Type in words: Record or null.
   */
  parallel: unknown;
  /**
   * Skipped lines, gaps of `seq`, majors seen and accepted, torn last line, fields cut, fields dropped
   *
   * Type in words: Record.
   */
  diagnostics: {
    skippedLines: number;
    gaps: Array<{
      after: number;
      before: number;
    }>;
    majorsSeen: Array<number>;
    majorsAccepted: {
      from: number;
      to: number;
    };
    majorsOutOfRange: number;
    tornLastLine: boolean;
    fieldsCut: Array<string>;
    fieldsDropped: Array<string>;
    redactorFailed: boolean;
  };
  /**
   * The change signature record and its 8-character token
   *
   * Type in words: Record, text.
   */
  signature: {
    record: Record<string, unknown>;
    token: string;
  };
  /**
   * The marks of the fold: the first and the newest event folded, and the times of `run.started` and `run.ended`. The place in the record where `project` keeps what it needs to recompute the age of the newest event (F129-FR-013) and the elapsed time (F129-FR-010) from a view alone, so that folding `reduce` event by event gives the same view as one batch (F129-FR-002).
   *
   * Type in words: Record.
   */
  stream: {
    first: unknown;
    last: unknown;
    runStartedAt: string | null;
    runEndedAt: string | null;
  };
  /**
   * The values `project` settled from the state files and the observations that the derivation re-reads. F129-FR-002 requires that such a field be recomputed by `project` at every call and never by `reduce`; `project` settles them once and the derivation reads them back from the record.
   *
   * Type in words: Record.
   */
  settled: {
    /**
     * The heartbeat of the lease is past its `validUntil` at `now`
     */
    heartbeatLate: boolean;
    /**
     * `status.staleEventSec`: the age after which the newest event counts as old
     */
    staleEventSec: number;
  };
}
